// Common Ground data model v2 (PLAN.md §5).
// Identity tables (user, organization, member, …) are generated by Better Auth into ./auth-schema.ts;
// app tables reference them here.

import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";
import { organization, user } from "./auth-schema";

const id = () => uuid("id").primaryKey().defaultRandom();
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

const orgRef = (name: string) => text(name).references(() => organization.id, { onDelete: "cascade" });
const userRef = (name: string) => text(name).references(() => user.id, { onDelete: "set null" });

// ── Organization profile ────────────────────────────────────────────────────

export const orgKind = pgEnum("org_kind", ["brand", "creator"]);

/** Every organization is either a brand (commissions work) or a creator (does the work). */
export const orgProfile = pgTable("org_profile", {
  organizationId: text("organization_id")
    .primaryKey()
    .references(() => organization.id, { onDelete: "cascade" }),
  kind: orgKind("kind").notNull(),
  isDemo: boolean("is_demo").notNull().default(false),
});

// ── Campaigns and immutable revisions ───────────────────────────────────────

export const campaignStatus = pgEnum("campaign_status", [
  "brief_draft",
  "researching",
  "reviewing_proposals",
  "in_production",
  "complete",
]);

export const campaign = pgTable(
  "campaign",
  {
    id: id(),
    /** Owning brand organization. */
    organizationId: orgRef("organization_id").notNull(),
    name: text("name").notNull(),
    status: campaignStatus("status").notNull().default("brief_draft"),
    isShowcase: boolean("is_showcase").notNull().default(false),
    currentRevisionId: uuid("current_revision_id").references((): AnyPgColumn => campaignRevision.id),
    createdAt: createdAt(),
  },
  (t) => [index("campaign_org_idx").on(t.organizationId)],
);

export const campaignType = pgEnum("campaign_type", ["ugc_production", "creator_distribution", "hybrid"]);

/** Immutable snapshot of everything a run depends on. Refinements create a new revision. */
export const campaignRevision = pgTable(
  "campaign_revision",
  {
    id: id(),
    campaignId: uuid("campaign_id")
      .notNull()
      .references(() => campaign.id, { onDelete: "cascade" }),
    number: integer("number").notNull(),
    parentRevisionId: uuid("parent_revision_id").references((): AnyPgColumn => campaignRevision.id),
    changeNote: text("change_note"),
    /** Structured brief (product, objective, deliverables, constraints); Zod-validated in app code. */
    brief: jsonb("brief").notNull(),
    campaignType: campaignType("campaign_type").notNull(),
    markets: text("markets").array().notNull(),
    languages: text("languages").array().notNull(),
    budgetCents: integer("budget_cents"),
    currency: text("currency").notNull().default("USD"),
    createdBy: userRef("created_by"),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("revision_number_uq").on(t.campaignId, t.number)],
);

export const inputSource = pgEnum("input_source", ["research", "team", "assumption"]);

/** An audience statement and where it came from; its source label follows it everywhere. */
export const briefInput = pgTable("brief_input", {
  id: id(),
  revisionId: uuid("revision_id")
    .notNull()
    .references(() => campaignRevision.id, { onDelete: "cascade" }),
  text: text("text").notNull(),
  source: inputSource("source").notNull(),
  confirmed: boolean("confirmed").notNull().default(false),
});

export const resolutionStatus = pgEnum("resolution_status", ["confirmed", "needs_input", "rejected"]);
export const qlooKind = pgEnum("qloo_kind", ["entity", "tag", "audience"]);

/** A brief reference resolved to a Qloo entity, tag or audience, with the user's confirmation. */
export const resolvedReference = pgTable(
  "resolved_reference",
  {
    id: id(),
    revisionId: uuid("revision_id")
      .notNull()
      .references(() => campaignRevision.id, { onDelete: "cascade" }),
    briefInputId: uuid("brief_input_id").references(() => briefInput.id, { onDelete: "set null" }),
    label: text("label").notNull(),
    qlooKind: qlooKind("qloo_kind").notNull(),
    qlooId: text("qloo_id"),
    qlooType: text("qloo_type"),
    /** Candidates offered for disambiguation (names + context, trimmed). */
    candidates: jsonb("candidates").notNull().default([]),
    status: resolutionStatus("status").notNull().default("needs_input"),
  },
  (t) => [index("resolved_reference_revision_idx").on(t.revisionId)],
);

// ── Durable runs ────────────────────────────────────────────────────────────

export const runMode = pgEnum("run_mode", ["qloo", "baseline"]);
export const runStatus = pgEnum("run_status", ["pending", "running", "needs_input", "done", "error", "cancelled"]);

export const run = pgTable(
  "run",
  {
    id: id(),
    revisionId: uuid("revision_id")
      .notNull()
      .references(() => campaignRevision.id, { onDelete: "cascade" }),
    mode: runMode("mode").notNull().default("qloo"),
    status: runStatus("status").notNull().default("pending"),
    cancelRequested: boolean("cancel_requested").notNull().default(false),
    /** Workflow SDK run id, for observability and resumption. */
    workflowRunId: text("workflow_run_id"),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("run_single_active_uq")
      .on(t.revisionId, t.mode)
      .where(sql`${t.status} in ('pending', 'running', 'needs_input')`),
  ],
);

export const runStage = pgTable(
  "run_stage",
  {
    id: id(),
    runId: uuid("run_id")
      .notNull()
      .references(() => run.id, { onDelete: "cascade" }),
    position: integer("position").notNull(),
    name: text("name").notNull(),
    status: runStatus("status").notNull().default("pending"),
    output: jsonb("output"),
    error: text("error"),
    startedAt: timestamp("started_at", { withTimezone: true }),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
  },
  (t) => [uniqueIndex("run_stage_position_uq").on(t.runId, t.position)],
);

// ── Qloo provenance and private cache ───────────────────────────────────────

export const qlooCall = pgTable(
  "qloo_call",
  {
    id: uuid("id").primaryKey(),
    campaignId: uuid("campaign_id").references(() => campaign.id, { onDelete: "cascade" }),
    runId: uuid("run_id").references(() => run.id, { onDelete: "cascade" }),
    endpoint: text("endpoint").notNull(),
    params: jsonb("params").notNull(),
    status: text("status").notNull(),
    httpStatus: integer("http_status"),
    latencyMs: integer("latency_ms").notNull(),
    cached: boolean("cached").notNull(),
    cacheKey: text("cache_key").notNull(),
    error: jsonb("error"),
    createdAt: createdAt(),
  },
  (t) => [index("qloo_call_campaign_idx").on(t.campaignId), index("qloo_call_run_idx").on(t.runId)],
);

/** Trimmed Qloo responses. Private server-side storage only (allowed by the hackathon terms). */
export const qlooCache = pgTable("qloo_cache", {
  cacheKey: text("cache_key").primaryKey(),
  response: jsonb("response").notNull(),
  createdAt: createdAt(),
});

// ── Evidence and claims ─────────────────────────────────────────────────────

export const evidenceKind = pgEnum("evidence_kind", [
  "tag",
  "entity",
  "demographic",
  "heatmap",
  "compare",
  "trend",
]);

/** One returned Qloo item with the values and query context it came from. */
export const evidence = pgTable(
  "evidence",
  {
    id: id(),
    runId: uuid("run_id")
      .notNull()
      .references(() => run.id, { onDelete: "cascade" }),
    kind: evidenceKind("kind").notNull(),
    qlooRef: text("qloo_ref"),
    label: text("label").notNull(),
    /** Values exactly as returned (affinity, attribution, skew, popularity…). */
    values: jsonb("values").notNull(),
    /** 1-based position in its result list, and that list's length: comparable only within one query. */
    rank: integer("rank"),
    resultCount: integer("result_count"),
    qlooCallId: uuid("qloo_call_id").references(() => qlooCall.id, { onDelete: "set null" }),
  },
  (t) => [index("evidence_run_idx").on(t.runId)],
);

export const claimOwner = pgEnum("claim_owner", ["direction", "proposal_version", "creator_fit"]);
export const claimKind = pgEnum("claim_kind", ["finding", "interpretation", "portfolio", "commercial"]);

/** A statement shown to users. Findings are written by templates, interpretations by the model. */
export const claim = pgTable(
  "claim",
  {
    id: id(),
    runId: uuid("run_id")
      .notNull()
      .references(() => run.id, { onDelete: "cascade" }),
    ownerType: claimOwner("owner_type").notNull(),
    ownerId: uuid("owner_id").notNull(),
    kind: claimKind("kind").notNull(),
    text: text("text").notNull(),
    createdBy: text("created_by").notNull(), // template | model
  },
  (t) => [
    index("claim_owner_idx").on(t.ownerType, t.ownerId),
    check("claim_finding_by_template", sql`${t.kind} <> 'finding' or ${t.createdBy} = 'template'`),
  ],
);

/** What a claim rests on: exactly one of evidence, a portfolio item, a quote, or another claim. */
export const claimBinding = pgTable(
  "claim_binding",
  {
    id: id(),
    claimId: uuid("claim_id")
      .notNull()
      .references(() => claim.id, { onDelete: "cascade" }),
    evidenceId: uuid("evidence_id").references(() => evidence.id, { onDelete: "cascade" }),
    portfolioItemId: uuid("portfolio_item_id").references(() => portfolioItem.id, { onDelete: "cascade" }),
    quoteId: uuid("quote_id").references(() => quote.id, { onDelete: "cascade" }),
    /** An interpretation binds to the finding claims it interprets. */
    findingClaimId: uuid("finding_claim_id").references((): AnyPgColumn => claim.id, { onDelete: "cascade" }),
    /** The bound field, e.g. "values.affinity" or "rank". */
    field: text("field"),
  },
  (t) => [
    index("claim_binding_claim_idx").on(t.claimId),
    check(
      "claim_binding_exactly_one",
      sql`num_nonnulls(${t.evidenceId}, ${t.portfolioItemId}, ${t.quoteId}, ${t.findingClaimId}) = 1`,
    ),
  ],
);

// ── Directions and checks ───────────────────────────────────────────────────

export const directionStatus = pgEnum("direction_status", ["active", "set_aside"]);

export const direction = pgTable(
  "direction",
  {
    id: id(),
    runId: uuid("run_id")
      .notNull()
      .references(() => run.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    audienceContext: text("audience_context").notNull(),
    productRole: text("product_role").notNull(),
    artDirection: jsonb("art_direction").notNull().default({}),
    colorIndex: integer("color_index").notNull().default(1),
    status: directionStatus("status").notNull().default("active"),
  },
  (t) => [index("direction_run_idx").on(t.runId)],
);

export const checkKind = pgEnum("check_kind", ["coherence", "sensitivity", "relevance"]);

export const directionCheck = pgTable(
  "direction_check",
  {
    directionId: uuid("direction_id")
      .notNull()
      .references(() => direction.id, { onDelete: "cascade" }),
    kind: checkKind("kind").notNull(),
    result: jsonb("result").notNull(),
    /** Inputs exercised by the check (e.g. which brief inputs were removed). */
    testedInputs: jsonb("tested_inputs").notNull().default([]),
  },
  (t) => [primaryKey({ columns: [t.directionId, t.kind] })],
);

// ── Creators ────────────────────────────────────────────────────────────────

export const creator = pgTable("creator", {
  id: id(),
  /** The creator's own organization. */
  organizationId: orgRef("organization_id").notNull(),
  isDemo: boolean("is_demo").notNull().default(false),
  displayName: text("display_name").notNull(),
  city: text("city").notNull(),
  country: text("country").notNull(),
  languages: text("languages").array().notNull().default([]),
  /** ugc_production | creator_distribution */
  modes: text("modes").array().notNull().default([]),
  bio: text("bio").notNull().default(""),
  proposition: text("proposition"),
  avatarUrl: text("avatar_url"),
  availability: jsonb("availability").notNull().default({}),
  declinedCategories: text("declined_categories").array().notNull().default([]),
  /** Distribution only; self-reported or authorized platform data, with its source. */
  audienceStats: jsonb("audience_stats"),
  createdAt: createdAt(),
});

export const portfolioItem = pgTable("portfolio_item", {
  id: id(),
  creatorId: uuid("creator_id")
    .notNull()
    .references(() => creator.id, { onDelete: "cascade" }),
  title: text("title").notNull(),
  imageUrl: text("image_url"),
  videoUrl: text("video_url"),
  role: text("role").notNull(),
  formats: text("formats").array().notNull().default([]),
  settings: text("settings").array().notNull().default([]),
  themes: text("themes").array().notNull().default([]),
  description: text("description").notNull().default(""),
});

/** Public cultural references the creator identifies with. Describes their work, never their followers. */
export const creatorReference = pgTable("creator_reference", {
  id: id(),
  creatorId: uuid("creator_id")
    .notNull()
    .references(() => creator.id, { onDelete: "cascade" }),
  label: text("label").notNull(),
  qlooId: text("qloo_id"),
  qlooType: text("qloo_type"),
  confirmed: boolean("confirmed").notNull().default(false),
});

/** Portfolio themes mapped to Qloo tags, confirmed by the creator. */
export const creatorTheme = pgTable("creator_theme", {
  id: id(),
  creatorId: uuid("creator_id")
    .notNull()
    .references(() => creator.id, { onDelete: "cascade" }),
  label: text("label").notNull(),
  tagId: text("tag_id"),
  confirmed: boolean("confirmed").notNull().default(false),
});

export const quote = pgTable("quote", {
  id: id(),
  creatorId: uuid("creator_id")
    .notNull()
    .references(() => creator.id, { onDelete: "cascade" }),
  /** null = the creator's standing rate card */
  campaignId: uuid("campaign_id").references(() => campaign.id, { onDelete: "cascade" }),
  package: text("package").notNull(),
  amountCents: integer("amount_cents").notNull(),
  currency: text("currency").notNull().default("USD"),
  usageTerms: text("usage_terms").notNull(),
  validUntil: timestamp("valid_until", { withTimezone: true }),
  source: text("source").notNull(), // rate_card | quote
  createdAt: createdAt(),
});

/** Separate dimensions on purpose: there is no single "match %". */
export const creatorFit = pgTable(
  "creator_fit",
  {
    runId: uuid("run_id")
      .notNull()
      .references(() => run.id, { onDelete: "cascade" }),
    creatorId: uuid("creator_id")
      .notNull()
      .references(() => creator.id, { onDelete: "cascade" }),
    directionId: uuid("direction_id")
      .notNull()
      .references(() => direction.id, { onDelete: "cascade" }),
    hardConstraints: jsonb("hard_constraints").notNull(),
    capability: jsonb("capability").notNull(),
    /** Per entity type: band within that query + coverage. Never aggregated across queries. */
    culturalBands: jsonb("cultural_bands").notNull(),
    shortlisted: boolean("shortlisted").notNull().default(false),
  },
  (t) => [primaryKey({ columns: [t.runId, t.creatorId, t.directionId] })],
);

// ── Proposals, versions, offers, packages ───────────────────────────────────

export const proposalStatus = pgEnum("proposal_status", [
  "draft",
  "saved",
  "quote_requested",
  "offered",
  "accepted",
  "declined",
  "set_aside",
]);

export const proposal = pgTable(
  "proposal",
  {
    id: id(),
    runId: uuid("run_id")
      .notNull()
      .references(() => run.id, { onDelete: "cascade" }),
    directionId: uuid("direction_id")
      .notNull()
      .references(() => direction.id, { onDelete: "cascade" }),
    creatorId: uuid("creator_id")
      .notNull()
      .references(() => creator.id, { onDelete: "cascade" }),
    currentVersionId: uuid("current_version_id").references((): AnyPgColumn => proposalVersion.id),
    status: proposalStatus("status").notNull().default("draft"),
  },
  (t) => [index("proposal_run_idx").on(t.runId)],
);

/** Immutable. Offers and acceptances reference an exact version. */
export const proposalVersion = pgTable(
  "proposal_version",
  {
    id: id(),
    proposalId: uuid("proposal_id")
      .notNull()
      .references(() => proposal.id, { onDelete: "cascade" }),
    number: integer("number").notNull(),
    authorUserId: userRef("author_user_id"),
    authorRole: text("author_role").notNull(), // agent | brand | creator
    concept: jsonb("concept").notNull(),
    deliverables: jsonb("deliverables").notNull(),
    terms: jsonb("terms").notNull(),
    hypothesis: text("hypothesis").notNull(),
    changeNote: text("change_note"),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("proposal_version_number_uq").on(t.proposalId, t.number)],
);

export const budgetPackage = pgTable("budget_package", {
  id: id(),
  runId: uuid("run_id")
    .notNull()
    .references(() => run.id, { onDelete: "cascade" }),
  kind: text("kind").notNull(), // concentrated | broad_test | production_heavy | hybrid
  proposalIds: uuid("proposal_ids").array().notNull(),
  costCents: integer("cost_cents").notNull(),
  rationale: text("rationale").notNull(),
});

export const offerStatus = pgEnum("offer_status", ["sent", "accepted", "declined", "withdrawn"]);

export const offer = pgTable("offer", {
  id: id(),
  proposalVersionId: uuid("proposal_version_id")
    .notNull()
    .references(() => proposalVersion.id),
  fromOrganizationId: orgRef("from_organization_id").notNull(),
  toOrganizationId: orgRef("to_organization_id").notNull(),
  status: offerStatus("status").notNull().default("sent"),
  sentBy: userRef("sent_by"),
  decidedBy: userRef("decided_by"),
  decidedAt: timestamp("decided_at", { withTimezone: true }),
  createdAt: createdAt(),
});

/** Campaign history: decisions, set-asides, revisions, offers. */
export const event = pgTable(
  "event",
  {
    id: id(),
    campaignId: uuid("campaign_id")
      .notNull()
      .references(() => campaign.id, { onDelete: "cascade" }),
    actorUserId: userRef("actor_user_id"),
    type: text("type").notNull(),
    payload: jsonb("payload").notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [index("event_campaign_idx").on(t.campaignId)],
);
